parameters.jsCode:
// Build Run Context — runOnceForAllItems.
//
// SCHEDULED 2026-08-30. The check page used to answer "How is it triggered? — Manual
// only"; the operator has ruled that every audit flow runs on a monthly schedule with
// no webhook in or out. The no-webhook half of the original reasoning is UNCHANGED and
// still right: the MV build cloned Travel Assist's `Validate Inputs` byte for byte and
// inherited a callback path and secret belonging to a different check, which it then had
// to report as an open gap. A check with one door does not need an intake adapter — and
// a schedule trigger is one door with no secret to get wrong at all.
//
// The two portal callback nodes were deleted in the same change. `Build Case Payload`
// and `Portal Delivery Declared?` are left in place but now lead nowhere; they are dead
// and can go in a tidy-up pass.
//
// Everything downstream reads its constants from HERE, and every constant on this
// page is the CC one.  Never import a value from MV Overstay Fines: that check is
// AED 300 recovered from the CLIENT on expense 1677, this one is AED 200 put on
// the MAID'S LOAN on expense 1589, and the two share a workbook.

// THE RUN WINDOW FOLLOWS THE CALENDAR (2026-08-30). It used to be two hand-edited
// constants, which a monthly schedule cannot use — an unattended run would have audited
// 2026-05-01..2026-08-31 forever. A run on the 15th audits the PREVIOUS FULL CALENDAR
// MONTH; the two-week lag is deliberate, because payments need time to settle.
//
// To pin a window for a deliberate one-off re-run, set the two OVERRIDE constants. Leave
// them null and the window follows the month automatically. Note the budget below is
// sized for the window the gate projects, so a WIDE pinned window may refuse to start —
// that is the gate working, not a fault.
const OVERRIDE_FROM = null;         // e.g. '2026-05-01'
const OVERRIDE_TO   = null;         // e.g. '2026-08-31'

function previousFullMonth() {
  const n = new Date();
  const first = new Date(Date.UTC(n.getUTCFullYear(), n.getUTCMonth() - 1, 1));
  const y = first.getUTCFullYear();
  const m = first.getUTCMonth() + 1;
  const lastDay = new Date(Date.UTC(y, m, 0)).getUTCDate();
  const p = function (x) { return String(x).padStart(2, '0'); };
  return { from: y + '-' + p(m) + '-01', to: y + '-' + p(m) + '-' + p(lastDay) };
}
const _win = previousFullMonth();
const WINDOW_FROM = OVERRIDE_FROM || _win.from;
const WINDOW_TO   = OVERRIDE_TO   || _win.to;
const IS_PINNED   = !!(OVERRIDE_FROM || OVERRIDE_TO);

// ERP-LOAD-POLICY.md §3. The pre-flight gate needs a budget and there is no webhook to carry
// one, so the knob lives here with the other two things an operator edits before a run. 2000 is
// the policy default, kept deliberately rather than pre-raised: the gate projects the WORST case
// (every case reaching the verifier band, up to 74 complaint threads each), so a wide window
// will refuse to start and say by how much. Raising this number is the recorded human decision
// §7 asks for — make it here, in the flow, where the next reader can see what was chosen.
const ERP_CALL_BUDGET = 2000;

const now = new Date().toISOString();

return [{
  json: {
    check_id: 'cc-overstay-fines',
    check_name: 'CC Overstay Fines',
    // The prefix and the trigger label record HOW the window was chosen, so a row in the
    // Runs table says whether a human picked it. Neither is branched on anywhere — they
    // are the record, not control flow.
    run_id: (IS_PINNED ? 'manual-' : 'sched-') + WINDOW_FROM.slice(0, 7) + '-' + now.slice(11, 19).replace(/:/g, ''),
    trigger: IS_PINNED ? 'manual' : 'scheduled',
    started_at: now,
    window_from: WINDOW_FROM,
    window_to: WINDOW_TO,

    // Named `params` so the gate reads it under the same key every other flow in this repo uses
    // (`params.erp_call_budget`), even though this check has no request body to put it in.
    params: {
      erp_call_budget: ERP_CALL_BUDGET
    },

    // Declared delivery targets.  Each one is wired as its OWN branch off the
    // node that produces the data — never chained behind another.  On the MV
    // build the whole post-verifier band sat behind `delivery.portal === true`
    // while the runner declared portal:false, so every AI verdict was discarded
    // and the review email, chained behind the portal callback, never fired.
    delivery: {
      // 2026-08-30: portal delivery is not merely undeclared, it is GONE - the two
      // callback nodes were deleted under the no-webhook ruling. This flag stays false
      // and there is no longer any node that reads it. Left in place because the payload
      // shape is stable and downstream readers expect the key.
      portal: false,
      data_tables: true,    // Cases / Runs / Verdicts
      // CORRECTED 2026-08-30. This read `false` with the note "produced outside the flow
      // from the Cases table", which has not been true since the flow gained its four
      // Google Sheets nodes (Cases / Verdicts / Run / Run-error). Under the ruling the
      // workbook IS the delivery mechanism, so the declaration now matches the wiring.
      workbook: true,
      email: false,         // the check page answers Email = no
      runs_log: true
    },

    // Inert, and now permanently so: the nodes that could have posted to it were
    // deleted on 2026-08-30. Kept only so the payload shape is stable.
    callback_url: '',

    constants: {
      expense_id: 1589,
      expense_name: 'NEW - CC Housemaids - Change of Status Application',
      base: 575.65,          // cc_change_of_status_base — CC's OWN measurement
      threshold: 200,        // strict > ; a TRIGGER, not a deductible
      day_rate: 50,
      loan_type: 'OVERSTAY_FINES_FEES'
    }
  }
}];

parameters.jsonBody:
={{ JSON.stringify([
  { property: "expense.id", operation: "=", value: 1589 },
  { property: "date", operation: "between", value: $('Build Run Context').first().json.window_from, secondValue: $('Build Run Context').first().json.window_to }
]) }}

parameters.jsCode:
// Build Error Callback — runOnceForAllItems.
//
// THE HEAD OF THE ERROR RAIL. Reached from the error output of every single-output node on the
// main path — the cohort sweep, `Acquire ERP Lease`, every Code node between the lease acquire
// and `Write Run`, and the three table writes — and from the workflow-level Error Trigger.
//
// It runs FIRST on the rail, before the lease is handed back, and that order is the whole reason
// the rail is shaped this way: an Execute Sub-workflow node replaces the item it is given with
// the sub-workflow's return value, so anything reading the failure has to read it before
// `Release Lease (error)` runs. The rail is therefore
//   failing node -> Build Error Callback -> Build Error Run Row -> Release Lease (error)
//                -> Fail Loudly (re-throws)
// with the callback and the failure draft hanging off this node as their own branches.
//
// ERP-COMPLIANCE: no-breaker-because this node reads ERROR ITEMS, not a batch of ERP responses.
// It is the first Code node downstream of `Get CC Change of Status Transactions`' error output,
// which is why §5 asks about it. That output carries exactly ONE item — the pager stops at the
// first page that fails — so consecutive_failures (needs 5) and degraded_rate (needs >= 20)
// cannot fire, and latency has no earlier batch of the same key in the same run to compare
// against. Judging a batch of one is the case ERP-LOAD-POLICY.md §5 names as the legitimate
// exemption. What stops the run instead is this rail itself: it records the failure, releases
// the ERP lease and re-throws at `Fail Loudly`, so the run cannot continue calling a failing ERP.
// The per-entity fan-outs are judged properly, by `Judge Detail/Fines/Loans/Complaints/Threads
// Batch`, each of which sits on its ERP node's REGULAR output precisely so failures reach a
// counter instead of being routed here.
//
// NOTE ON THE 498-INSIDE-500 SHAPE. ERP answers an expired token with HTTP 500 carrying
// "Token not valid, {Token is expired}", not a clean 401. The classification order below
// therefore lets the message win over the 5xx status for token text, so a dead token is
// filed as `erp_auth` ("get a fresh token") rather than `erp_server` ("ERP is broken").
// Wellcare's run-config node documents the same shape.
//
// It does NOT end the run quietly.  On the MV build the error rail caught an ERP
// failure, drafted an alert and exited cleanly, so n8n recorded `status: success`
// for a run that audited nothing — and because `Build Run Row` sat downstream of
// the case payload, a failed run wrote NO Runs row at all, from the log whose
// stated purpose is "there is always a record that it ran".  Here the rail writes
// a Runs row first and then deliberately fails the execution.

const items = $input.all();
let run = { run_id: 'unknown', check_id: 'cc-overstay-fines', check_name: 'CC Overstay Fines',
            window_from: '', window_to: '', trigger: 'manual', callback_url: '' };
try { run = Object.assign(run, $('Build Run Context').first().json); } catch (e) { /* crash before intake */ }

const seen = {};
const errors = [];

// WHICH node failed.  An HTTP node's error item does NOT carry its own name in
// the payload — the first live error test of this rail reported node "unknown",
// which is useless in an alert.  n8n exposes the sender as `$prevNode`, and that
// is the only place the name actually is.
let prevNodeName = '';
try { prevNodeName = ($prevNode && $prevNode.name) || ''; } catch (e) { prevNodeName = ''; }

for (const it of items) {
  const j = it.json || {};

  // THREE shapes, not two. FIXED 2026-08-30 after this node reported "unknown error"
  // on three consecutive live runs about failures the source had described exactly:
  //
  //   1. Error Trigger envelope      j.execution.error  -> object, {message, httpCode}
  //   2. HTTP node error output      j.error            -> object, but the status is on
  //                                                       `statusCode` (NOT httpCode/status,
  //                                                       which is all the old reader looked
  //                                                       at) and the ERP body is a JSON
  //                                                       STRING under `error`
  //   3. Code node throw             j.error            -> a plain STRING
  //
  // Shape 3 was the worst: `err.message` on a string is undefined, so every Code-node throw
  // - including every circuit-breaker trip - was recorded as "unknown error". Measured on
  // execution 110239, where the breaker's own actionable sentence was discarded.
  // Shape 2 lost BOTH the status and the message: exec 110226, where ERP said
  // "Token not valid, {Token is expired}" and this node recorded null / unknown.
  const rawErr = j.error !== undefined ? j.error
               : ((j.execution || {}).error !== undefined ? (j.execution || {}).error : j);
  const errIsString = (typeof rawErr === 'string');
  const err = errIsString ? {} : (rawErr || {});

  // The ERP body arrives as a JSON string on shape 2. Parse it rather than regexing it;
  // if it is not JSON, fall back to using the raw string as the message below.
  let inner = {};
  if (typeof err.error === 'string') {
    try { inner = JSON.parse(err.error) || {}; } catch (e) { inner = {}; }
  } else if (err.error && typeof err.error === 'object') {
    inner = err.error;
  }

  // Classify on the STATUS CODE first where there is one - the message text is the least
  // reliable thing in an error. Every place a status has actually been observed is checked.
  const status = j.statusCode || err.statusCode || err.httpCode || err.status ||
                 (err.response && err.response.status) || inner.status || null;
  const node = (j.node && j.node.name) || (err.node && err.node.name) ||
               (j.execution || {}).lastNodeExecuted || prevNodeName || 'unknown';
  const message = (errIsString ? rawErr : null) ||
                  inner.message || err.message || err.description ||
                  (typeof err.error === 'string' ? err.error : null) ||
                  j.message || 'unknown error';

  let code = 'erp_error';
  const st = String(status || '');
  // An explicit 401 is unambiguous and wins outright. The breaker check sits ABOVE the loose
  // /token/ test on purpose: the breaker's own message contains the words "live token", so a
  // text-only test would file a self-protective trip as an auth failure and send the reader
  // hunting for a credential problem that may not exist.
  if (st === '401') code = 'erp_auth';
  else if (/ERP-LOAD-POLICY|refusal that is total|circuit breaker/i.test(message)) code = 'erp_breaker_trip';
  else if (/token|unauthor/i.test(message)) code = 'erp_auth';
  else if (st === '403') code = 'erp_permission';
  else if (st === '404') code = 'erp_not_found';
  else if (st === '429') code = 'erp_rate_limited';
  else if (st.charAt(0) === '5') code = 'erp_server';
  else if (/timeout|ETIMEDOUT|ECONNRESET/i.test(message)) code = 'erp_timeout';
  else if (/paired item/i.test(message)) code = 'item_linking';

  const key = code + '|' + node;
  if (seen[key]) { seen[key].occurrences++; continue; }
  const rec = { code, node, status: status || null, message: String(message).slice(0, 500), occurrences: 1 };
  seen[key] = rec;
  errors.push(rec);
}

if (errors.length === 0) {
  errors.push({ code: 'unknown', node: 'unknown', status: null, message: 'The error rail fired with no readable error payload.', occurrences: 1 });
}

const primary = errors[0];

return [{
  json: {
    result: 'error',
    check_id: run.check_id,
    check_name: run.check_name,
    run_id: run.run_id,
    window_from: run.window_from,
    window_to: run.window_to,
    trigger: run.trigger,
    callback_url: run.callback_url,
    delivery: run.delivery || { portal: false, data_tables: true },
    error: primary,
    errors,
    failed_at: new Date().toISOString(),
    // Read straight from the owner if it got that far. An error before the cohort
    // walk leaves this empty, which is the honest answer.
    population: (function () {
      try { return $('Verify Cohort Pull').first().json.population; } catch (e) { return {}; }
    })()
  },
  pairedItem: { item: 0 }
}];

// Verify Cohort Pull — runOnceForAllItems.
//
// THIS NODE OWNS THE POPULATION PROOF.  Every downstream consumer reads it from
// here by name — `$('Verify Cohort Pull').first().json.population` — and never
// from whatever survived three transforms.  On the MV build the proof arrived at
// `Build Run Row` as `{}` because an intermediate node dropped it, so every run
// wrote `population_complete: false` and stamped itself untrustworthy.
//
// 2026-08-30: the cohort now also carries IDENTITY.  The route moved from
// `advancesearchNew` to the legacy `advancesearch`, whose projection includes the
// `housemaids` link.  Identity therefore arrives with the population instead of
// costing one ERP call per transaction, and `Get Transaction Detail` is gone.
//
// Four separate obligations, none of which is the others:
//   (a) PAGINATION.  Summed content.length must equal totalElements.  Measured
//       live 2026-08-12 across nine months (963 rows): complete every month.
//   (b) EMPTY ABORTS.  An empty result is never "no findings".  A month with zero
//       CC change-of-status transactions is a broken query — the cohort row's own
//       Default Value says so.
//   (c) NO FOREIGN EXPENSE.  expense.id 1589 only.  The MV expense is 1677; the
//       names differ by three characters and the codes by one digit, and reading
//       the wrong one audits an entirely different population while every gate
//       still passes and the walk still terminates cleanly.
//   (d) ATTRIBUTION PRESENT.  New, and it exists to catch exactly one regression:
//       `advancesearchNew` returns rows IDENTICAL to `advancesearch` in every
//       field this node reads EXCEPT `housemaids`, which it omits entirely.  If
//       anyone repoints the URL back, (a), (b) and (c) all still pass, every case
//       then fails gate 3, and the run reports a clean month it never audited.
//       Measured 2026-08-30 on the live CC cohort: 200 of 200 rows carried
//       attribution.  Zero is not a thin month; it is the wrong endpoint.
//
// ERP-COMPLIANCE: no-breaker-because this node reads a PAGINATED SWEEP, not a per-entity batch.
// ERP-LOAD-POLICY.md §5 wants the breaker wherever a batch of ERP responses is read, and none of
// its three thresholds can do useful work on this one:
//   * consecutive_failures needs five responses in a row. The pager stops at the FIRST failing
//     page — `Get CC Change of Status Transactions` is on continueErrorOutput, so page N's
//     failure ends the walk and goes straight to the error rail. There can never be a second
//     failure to count, let alone a fifth. The walk aborting sooner than a breaker reading the
//     finished batch is not a gap; it is a stricter rule.
//   * degraded_rate needs >= 20 responses. Measured 2026-08-12, nine months of cohort is 963
//     rows at size=200 — five pages. A window would have to cover roughly thirty years to
//     produce twenty of them, and `maxRequests` caps the walk at fifty pages anyway.
//   * latency needs an earlier batch of the same key in the same run. There is exactly one
//     cohort walk per run.
// What stops the run instead: the four throws below, the pager's own `maxRequests: 50`, and the
// error rail, which releases the ERP lease and re-throws at `Fail Loudly`.

const pages = $input.all();
const EXPENSE_ID = 1589;

let rows = [];
let reported = null;
for (const p of pages) {
  const b = p.json && p.json.body !== undefined ? p.json.body : p.json;
  const content = (b && b.content) || [];
  if (!Array.isArray(content)) {
    throw new Error('Cohort page did not carry a content array — the response shape changed.');
  }
  rows = rows.concat(content);
  if (reported === null && b && typeof b.totalElements === 'number') reported = b.totalElements;
}

// (b) EMPTY ABORTS — before anything else, so an empty month cannot be reported clean.
if (rows.length === 0) {
  throw new Error(
    'CC change-of-status cohort returned ZERO transactions for the window. ' +
    'An empty result is a broken query, never "no findings" — the run is aborted.'
  );
}

// (a) PAGINATION
const complete = (reported === null) ? false : (rows.length === reported);
if (!complete) {
  throw new Error(
    'Cohort walk incomplete: pulled ' + rows.length + ' rows but the envelope reports ' +
    reported + ' totalElements. Never audit a truncated population.'
  );
}

// (c) NO FOREIGN EXPENSE
const foreign = Array.from(new Set(
  rows.map((r) => (r.expense || {}).id).filter((id) => id !== EXPENSE_ID)
));
if (foreign.length) {
  throw new Error('Foreign expense ids in the cohort: ' + JSON.stringify(foreign) +
                  '. Only 1589 belongs to this check.');
}

const cohort_rows = rows.map((r) => ({
  txn_id: String(r.id),
  txn_amount: typeof r.amount === 'number' ? r.amount : null,
  txn_date: r.date || '',
  vat_amount: r.vatAmount,
  expense_id: (r.expense || {}).id,
  // Identity, carried from the population row itself.  Reshaped rather than passed
  // through whole: the raw link also carries attachments, creator and modification
  // stamps that nothing downstream reads, and a case row is not a place to park
  // fields no gate has a use for.
  housemaids: (Array.isArray(r.housemaids) ? r.housemaids : []).map((h) => ({
    housemaid: {
      id: (h.housemaid || {}).id,
      label: (h.housemaid || {}).label
    },
    contractId: h.contractId,
    amount: h.amount
  }))
  // `description` is deliberately NOT carried forward.  It contains the maid's
  // name and must never be able to resolve an identity (gate 3).
}));

// (d) ATTRIBUTION PRESENT — the endpoint-regression guard described above.
const rows_with_attribution = cohort_rows.filter((r) => r.housemaids.length > 0).length;
if (rows_with_attribution === 0) {
  throw new Error(
    'Cohort carried ' + cohort_rows.length + ' transactions and NOT ONE of them carried a ' +
    'housemaids link. On the legacy /accounting/transactions/page/advancesearch route this is ' +
    'impossible for the CC change-of-status expense — 200 of 200 rows carried attribution when ' +
    'this was measured live on 2026-08-30. The overwhelmingly likely cause is that the URL has ' +
    'been repointed at /advancesearchNew, whose DTO omits housemaids while every other field ' +
    'this node reads looks identical. Aborting: without identity every case would fail gate 3 ' +
    'and the run would report a clean month it never actually audited.'
  );
}

return [{
  json: {
    population: {
      cohort_count: cohort_rows.length,
      total_elements_reported: reported,
      pages_fetched: pages.length,
      population_complete: complete,
      foreign_expense_ids: foreign,
      expense_id: EXPENSE_ID,
      // Published so partial attribution is visible as a measured fact. Nothing
      // throws on a shortfall short of zero — a single unlinked transaction is a
      // real data condition and gate 3 already routes it to review.
      rows_with_attribution,
      rows_without_attribution: cohort_rows.length - rows_with_attribution
    },
    cohort_rows
  },
  pairedItem: { item: 0 }
}];

// Split Transactions — runOnceForAllItems.
//
// Intake gates 1 and 2.  Filtering happens HERE, at intake, not at scoring, and
// the excluded counts are published so "out of scope" can never be reported as
// "clean".
//
// PAIRED ITEM.  n8n only auto-pairs Run-Once-for-EACH-Item nodes.  This node runs
// once for all items and reshapes them, so it sets `pairedItem` itself or every
// downstream `.item` lookup throws "Paired item data ... is unavailable".  There
// is exactly one input item here (Verify Cohort Pull emits one envelope), so
// `{ item: 0 }` is the honest pairing, not a convenient one.
//
// Never "fix" a missing pairing by swapping `.item` for `.first()` downstream, as
// n8n's own error text suggests: `.first()` returns input item 0 for EVERY item
// and would attach the wrong maid to every case after the first.

const env = $input.first().json;
const rows = env.cohort_rows || [];
const c = $('Build Run Context').first().json.constants;
const BASE = c.base;              // 575.65 — CC's own constant
const EXPENSE_ID = c.expense_id;  // 1589

let excluded_wrong_expense = 0;
let excluded_at_or_below_base = 0;
let excluded_unreadable_amount = 0;

const cases = [];
const unreadable = [];

for (const r of rows) {
  // Gate 1 — population is the CC change-of-status expense, and nothing else.
  // Never widen the expense filter to find more.
  if (r.expense_id !== EXPENSE_ID) { excluded_wrong_expense++; continue; }

  // Gate 2 — overstay exists only where the amount EXCEEDS the base.
  // Never treat a missing or unreadable amount as the base: that silently means
  // "no overstay" and drops a real case.  Route it to review instead.
  if (typeof r.txn_amount !== 'number' || !isFinite(r.txn_amount)) {
    excluded_unreadable_amount++;
    unreadable.push(r);
    continue;
  }
  // Never re-derive the base from the month's data — the modal amount would move
  // the moment a month carried more overstay than clean rows.
  if (!(r.txn_amount > BASE)) { excluded_at_or_below_base++; continue; }

  cases.push({
    case_key: r.txn_id,
    txn_id: r.txn_id,
    txn_amount: r.txn_amount,
    txn_date: r.txn_date,
    vat_amount: r.vat_amount,
    expense_id: r.expense_id,
    excess: Math.round((r.txn_amount - BASE) * 100) / 100,
    // Carried, not looked up.  Identity now rides on the cohort row (see
    // `Verify Cohort Pull`), so `Attach Identity` reads it from here rather than
    // from a per-transaction ERP call.  Kept under its original key so the gate-3
    // contract — `housemaids[0].housemaid.id`, and nothing else — is unchanged.
    housemaids: r.housemaids || []
  });
}

const intake_stats = {
  cohort_count: rows.length,
  excluded_wrong_expense,
  excluded_at_or_below_base,
  excluded_unreadable_amount,
  txns_with_overstay: cases.length
};

const out = [];
for (const k of cases) {
  out.push({ json: Object.assign({ no_cases: false, intake_stats }, k), pairedItem: { item: 0 } });
}
for (const r of unreadable) {
  out.push({
    json: {
      no_cases: false, intake_stats,
      case_key: r.txn_id, txn_id: r.txn_id, txn_amount: null, txn_date: r.txn_date,
      expense_id: r.expense_id, excess: null,
      housemaids: r.housemaids || [],
      unreadable_amount: true
    },
    pairedItem: { item: 0 }
  });
}

// A month can legitimately carry ZERO over-base transactions — measured live,
// May 2026 (142 txns) and June 2026 (274 txns) both did.  Emitting nothing here
// would strand the whole downstream band, and no Runs row would be written for a
// run that genuinely completed.  The sentinel keeps the run alive so the log
// whose stated purpose is "there is always a record that it ran" gets one.
if (out.length === 0) {
  out.push({ json: { no_cases: true, intake_stats }, pairedItem: { item: 0 } });
}

return out;

// Attach Identity — runOnceForEachItem.
//
// Gate 3: identity resolution before anything else.  The maid comes from
// `housemaids[0].housemaid.id` and from nowhere else.
//
// 2026-08-30: that link no longer arrives from a per-transaction detail call. The
// cohort route moved to the legacy /accounting/transactions/page/advancesearch,
// whose projection already carries `housemaids`, so identity is read off the case
// row `Split Transactions` built.  The gate-3 CONTRACT is unchanged — same field,
// same position, same refusal to infer — only its source moved upstream, and one
// ERP call per over-base transaction disappeared with it.
//
// Never resolve a maid from the transaction `description`, even though it plainly
// contains her name — which is why `Verify Cohort Pull` refuses to carry it.
// Never join a transaction to a fine or a loan by amount, date or name — two maids
// with the same day count carry an identical fine, and that coincidence has
// already produced a false link on the MV side.
//
// `housemaids[0].contractId` is almost always EMPTY on CC transactions (unlike MV):
// measured 2026-08-30 over 200 live cohort rows, 199 empty and 1 populated.  So
// there is effectively no contract to scope anything to, and the one that exists
// is not a base to build on.  Identity here is the maid, full stop, and recovery
// is read from her loans rather than from client payments.

const carry = $('Split Transactions').item.json;

// The case row IS the identity source now.  `carry` and `$json` are the same item
// on this path; reading `carry` states which one is meant, so a future node
// inserted in between cannot silently change what this gate sees.
const hms = (carry && carry.housemaids) || [];
const h0 = hms[0] || {};
const maid = h0.housemaid || {};
const maid_id = (maid.id === 0 || maid.id) ? String(maid.id) : '';

return {
  json: Object.assign({}, carry, {
    maid_id,
    maid_name: maid.label || '',
    // Recorded so the emptiness is visible as a measured fact rather than a
    // missing key someone later "fixes" by scoping a lookup to it.
    contract_id_on_txn: (h0.contractId === 0 || h0.contractId) ? String(h0.contractId) : '',
    housemaids_len: hms.length,
    identity_resolved: !!maid_id
  })
};

// Attach Fines — runOnceForEachItem.
//
// `GET /visa/overstay-fines/housemaid/{id}` returns a BARE JSON ARRAY.  n8n splits
// a top-level array into ONE ITEM PER ELEMENT, so without `fullResponse: true` on
// the HTTP node this node would receive a single fine OBJECT — and a maid with
// ZERO fines would produce ZERO items and vanish from the run entirely, while a
// maid with two would produce two.  That is exactly what happened on the MV build:
// all 30 cases came out `fines_unreadable`.  With fullResponse the array arrives
// under `body` and there is exactly one item per input for 0, 1 or N rows.
//
// This node NORMALISES.  It does not score.

const carry = $('Attach Identity').item.json;
const c = $('Build Run Context').first().json.constants;

const payload = $json.body !== undefined ? $json.body : $json;
const fines_readable = Array.isArray(payload);
const raw = fines_readable ? payload : [];

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return isFinite(n) ? n : null;
}

// `reductionReason` is documented as an OBJECT {id,label} — that is its MV shape.
// Live CC data (67 fine rows read 2026-08-12) returns a plain EMPTY STRING for it
// on every row.  Both shapes must be handled: as text an object writes
// "[object Object]" into the case, and as an object a string throws.
function reason(v) {
  if (v && typeof v === 'object') return v.label || '';
  return typeof v === 'string' ? v : '';
}

const all_rows = raw.map((f) => ({
  fine_id: (f.id === 0 || f.id) ? String(f.id) : '',
  gross: num(f.originalOverstayFees),
  net: num(f.overstayFineAmount),
  days: num(f.numOfOverstayDays),
  reduced_amount: num(f.reducedAmount),
  reduction_reason: reason(f.reductionReason),
  // Context only.  overstayFinesStatus and datePaid are not maintained — never
  // gate on them.
  status: f.overstayFinesStatus || '',
  date_paid: f.datePaid || '',
  housemaid_type: ((f.housemaid || {}).housemaidType) || ''
}));
// phoneNumber is present on the housemaid sub-object and is deliberately dropped.
// This check must never carry a phone number.

// Placeholder rows: net AND days both zero.  Counting one as a case invents a
// fine that does not exist.  Measured live: 30 of 65 over-base transactions had
// nothing BUT placeholder rows.
const surviving = all_rows.filter((f) => (f.net || 0) !== 0 || (f.days || 0) !== 0);

// MV maids are out of scope entirely — road-map #24, threshold 300, recovered
// from the client.  `housemaidType` is the discriminator: CC reads 'Normal', MV
// reads 'MaidVisa'.  Five fine rows inside the CC 1589 population read 'MaidVisa'
// live on 2026-08-12, so this exclusion genuinely fires and is not theoretical.
const mv_rows = all_rows.filter((f) => f.housemaid_type === 'MaidVisa');
const is_mv_maid = mv_rows.length > 0 && mv_rows.length === all_rows.length;

// Never join a transaction to a fine by amount, date or name (gate 3).  So the
// fine is taken only when it is UNAMBIGUOUS: exactly one surviving row.  Across
// nine months of live data every maid had 0 or 1 surviving row, so the ambiguous
// branch has never fired — it exists so that if it ever does, the case goes to a
// human instead of being amount-matched.
let fine = null;
let fine_ambiguous = false;
if (surviving.length === 1) fine = surviving[0];
else if (surviving.length > 1) fine_ambiguous = true;

return {
  json: Object.assign({}, carry, {
    fines_readable,
    fine_rows_total: all_rows.length,
    fine_rows_surviving: surviving.length,
    fine_ambiguous,
    fine_rows: surviving,
    is_mv_maid,
    housemaid_type: (all_rows[0] || {}).housemaid_type || '',
    fine_id: fine ? fine.fine_id : '',
    fine_gross: fine ? fine.gross : null,
    fine_net: fine ? fine.net : null,
    fine_days: fine ? fine.days : null,
    fine_reduced_amount: fine ? fine.reduced_amount : null,
    fine_reduction_reason: fine ? fine.reduction_reason : '',
    fine_status: fine ? fine.status : ''
  })
};

// Attach Loans — runOnceForEachItem.
//
// `GET /payroll/loans/getHousemaidLoans/{id}` also returns a BARE JSON ARRAY, so
// it carries the identical trap as the fines endpoint and the HTTP node in front
// of this one also sets `fullResponse: true`.  Checked, not assumed: 83 loans
// across 64 maids read live 2026-08-12, always as a top-level array.
//
// Gate 8 — recovery is the SUM of OVERSTAY_FINES_FEES loans, compared on
// `amount` (principal).
//   Never compare against `remainingAmount`: repayments shrink it toward zero, so
//   a correctly loaded loan reads as never added.  Live proof of the shape sits in
//   this very corpus — loan 79063 has amount 323 and remainingAmount 0.
//   Never gate on `status`: it came back an EMPTY STRING on loan 80186 (a correct
//   case) and "Not Yet Paid" on 2024 loans.
//   Never require the loan date to match the transaction date: loan 80186 is
//   dated a day before its own transaction.
//   A maid can carry several such loans and one may have no transaction behind
//   it — sum them rather than expecting one (gate 10).

const carry = $('Attach Fines').item.json;
const LOAN_TYPE = $('Build Run Context').first().json.constants.loan_type;

const payload = $json.body !== undefined ? $json.body : $json;
const loans_readable = Array.isArray(payload);
const raw = loans_readable ? payload : [];

function num(v) {
  if (v === null || v === undefined || v === '') return null;
  const n = Number(v);
  return isFinite(n) ? n : null;
}
const r2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

const os_loans = raw
  .filter((l) => l && l.loanType === LOAN_TYPE)
  .map((l) => ({
    loan_id: (l.id === 0 || l.id) ? String(l.id) : '',
    amount: num(l.amount) || 0,
    waived_amount: num(l.waivedAmount) || 0,
    remaining_amount: num(l.remainingAmount),
    repaid_amount: num(l.repaidAmount),
    // status is captured for the reviewer and NEVER gated on.
    status: typeof l.status === 'string' ? l.status : '',
    loan_date: l.loanDate || '',
    waive_notes: typeof l.waiveNotes === 'string' ? l.waiveNotes : '',
    repayment_notes: typeof l.repaymentNotes === 'string' ? l.repaymentNotes : ''
  }));

const loan_sum = r2(os_loans.reduce((a, l) => a + l.amount, 0));
// waivedAmount 0.0 is the NORMAL value on an unwaived loan — every one of the 27
// OVERSTAY_FINES_FEES loans read live carried 0.0.  Reading it as a waiver would
// clear every case.
const waived_sum = r2(os_loans.reduce((a, l) => a + l.waived_amount, 0));
const waived = waived_sum > 0;

return {
  json: Object.assign({}, carry, {
    loans_readable,
    loans_total: raw.length,
    os_loans,
    os_loan_count: os_loans.length,
    loan_sum,
    waived_sum,
    waived,
    waive_notes: os_loans.map((l) => l.waive_notes).filter(Boolean).join(' || '),
    repayment_notes: os_loans.map((l) => l.repayment_notes).filter((s) => s && s !== '-').join(' || '),
    other_loan_types: Array.from(new Set(raw.map((l) => l && l.loanType).filter(Boolean)))
  })
};

// Compute Case States — runOnceForAllItems.
//
// The eleven deterministic gates, IN THE ORDER the Audit Conditional Policy — CC
// Maid lists them.  Every "Never" line from that page is carried here as a
// comment at the point where it constrains the code.
//
// NO GAP TOLERANCE.  This check declares none, and none is borrowed from another
// check.  `r2()` exists only to defeat IEEE noise on sums, not as a tolerance.
//
// THE CONSTANTS ON THIS PAGE ARE CC'S.  Threshold 200, strict `>`, and it is a
// TRIGGER not a deductible: above 200 the WHOLE fine goes on the maid's loan.
// MV Overstay Fines is 300 and the CLIENT pays.  The two checks share one
// workbook and that is exactly how a shared constant gets introduced by accident.

const c = $('Build Run Context').first().json.constants;
const THRESHOLD = c.threshold;   // 200
const DAY_RATE = c.day_rate;     // 50
const r2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

const items = $input.all().map((i) => i.json);
const intake_stats = (items[0] && items[0].intake_stats) || {};

const cases = [];
const excluded_mv = [];

for (const it of items) {
  if (it.no_cases === true) continue;          // the empty-month sentinel

  const base = {
    case_key: it.case_key,
    txn_id: it.txn_id,
    txn_date: it.txn_date || '',
    txn_amount: it.txn_amount,
    excess: it.excess,
    maid_id: it.maid_id || '',
    maid_name: it.maid_name || '',
    contract_id_on_txn: it.contract_id_on_txn || '',
    housemaid_type: it.housemaid_type || '',
    fine_id: it.fine_id || '',
    fine_gross: it.fine_gross,
    fine_net: it.fine_net,
    fine_days: it.fine_days,
    fine_reduced_amount: it.fine_reduced_amount,
    fine_reduction_reason: it.fine_reduction_reason || '',
    os_loan_count: it.os_loan_count || 0,
    os_loans: it.os_loans || [],
    loan_sum: it.loan_sum || 0,
    waived_sum: it.waived_sum || 0,
    waive_notes: it.waive_notes || '',
    repayment_notes: it.repayment_notes || '',
    // Informational only — it changes no verdict.  Real overstay fines are an
    // exact multiple of 50 (fifty dirhams a day).  Measured live, 29 Feb/Mar 2026
    // transactions carry an excess of exactly 14.89 against no fine record at
    // all, which looks like a repriced base rather than an overstay.  Grouping
    // them lets a reviewer see that at a glance instead of reading 29 identical
    // "no fine record" reviews.
    excess_shape: (typeof it.excess === 'number' && it.excess > 0 &&
                   Math.abs(it.excess % DAY_RATE) < 0.005) ? 'multiple_of_50' : 'other',
    days_x50_ok: null,
    expected_aed: null,
    recovered_aed: it.loan_sum || 0,
    gap_aed: null,
    surplus_aed: null,
    sub200_recovered_aed: null,
    needs_verifier: false,
    state: '',
    reason_code: '',
    reason_text: '',
    mentions: []
  };

  // ---- OUT OF SCOPE: MV maids -------------------------------------------
  // Road-map #24, threshold 300, recovered from the CLIENT.  housemaidType is the
  // discriminator: CC reads 'Normal', MV reads 'MaidVisa'.
  if (it.is_mv_maid) {
    excluded_mv.push({ case_key: it.case_key, maid_id: it.maid_id });
    continue;
  }

  // ---- Gate 3 — identity resolution before anything else ----------------
  // Empty housemaids[] goes to review UNATTRIBUTED.  Never fall back to the
  // description name.
  if (it.unreadable_amount) {
    cases.push(Object.assign(base, {
      state: 'review', reason_code: 'unreadable_amount',
      reason_text: 'The transaction amount could not be read as a number, so whether it carries overstay is unknown. Never treated as the base.'
    }));
    continue;
  }
  if (!it.identity_resolved) {
    cases.push(Object.assign(base, {
      state: 'review', reason_code: 'unattributed',
      reason_text: 'The transaction detail carried no housemaids[] entry, so the fine cannot be attributed to a maid. Never resolved from the description.'
    }));
    continue;
  }
  if (it.fines_readable === false) {
    cases.push(Object.assign(base, {
      state: 'review', reason_code: 'fines_unreadable',
      reason_text: 'The overstay-fines endpoint did not return a list. Never read as "no fine".'
    }));
    continue;
  }
  if (it.loans_readable === false) {
    cases.push(Object.assign(base, {
      state: 'review', reason_code: 'loans_unreadable',
      reason_text: 'The loans endpoint did not return a list. Never read as "nothing recovered".'
    }));
    continue;
  }

  // ---- Gate 11 — no fine record against a transaction excess -------------
  // Never read an empty fine record as nothing owed: the 2024 cohort returns no
  // rows at all, so an empty result can mean the record predates the feature.
  // Never bill or loan from this state — there is no authoritative amount.
  if (it.fine_ambiguous) {
    cases.push(Object.assign(base, {
      state: 'review', reason_code: 'fine_ambiguous',
      reason_text: 'The maid carries more than one live overstay-fine row, and a transaction is never joined to a fine by amount, date or name. A human must pick the right row.'
    }));
    continue;
  }
  if (base.fine_net === null || base.fine_net === undefined) {
    cases.push(Object.assign(base, {
      state: 'review', reason_code: 'no_fine_record',
      reason_text: 'The transaction carries an excess of ' + base.excess +
        ' over the base but the maid\'s overstay-fines record returned nothing usable' +
        (base.excess_shape === 'other' ? ' (and the excess is not a multiple of 50, so it may not be an overstay at all)' : '') + '.'
    }));
    continue;
  }

  // ---- Gate 4 — the fine must reconcile to fifty dirhams a day -----------
  // A mismatch is a DATA-QUALITY flag; the case still proceeds on the fine
  // record's own figure.  Never substitute days x 50 for the fine, and never
  // silently correct one to match the other.
  const expect_gross = (base.fine_days || 0) * DAY_RATE;
  base.days_x50_ok = (base.fine_gross !== null) && Math.abs(base.fine_gross - expect_gross) < 0.005;
  if (!base.days_x50_ok) {
    base.mentions.push('data_quality: gross ' + base.fine_gross + ' != days ' +
                       base.fine_days + ' x ' + DAY_RATE + ' = ' + expect_gross);
  }

  // ---- Gate 7 — a waiver on the FINE record clears the expectation -------
  // reducedAmount and reductionReason are read BEFORE any comparison.  Never
  // raise a missing-loan finding without having read the waiver first: on the MV
  // side this exact mechanism accounted for 19 of 20 reported findings.
  // reductionReason is documented as an object {id,label} and arrives as a plain
  // string on live CC data — Attach Fines normalises both, so it is never
  // "[object Object]" here.
  const reduced = base.fine_reduced_amount || 0;
  if (reduced > 0) {
    if ((base.fine_net || 0) === 0 && String(base.fine_reduction_reason).trim() !== '') {
      cases.push(Object.assign(base, {
        expected_aed: 0, gap_aed: 0, state: 'green',
        reason_code: 'fine_waived_explained',
        reason_text: 'The fine was reduced to zero. Reason on the record: "' +
                     base.fine_reduction_reason + '". Nothing is owed, so nothing was expected on her loan.'
      }));
      continue;
    }
    // A reduction with no stated ground is exactly the shape this check exists to
    // surface.  Never clear on it here — the verifier judges whether the reason
    // says WHY (verifier rule 2).
    base.needs_verifier = true;
    base.mentions.push('fine reduced by ' + reduced + ' with reason "' +
                       (base.fine_reduction_reason || '(blank)') + '"');
  }

  // ---- Gate 5 — two hundred dirhams is a TRIGGER, not a deductible -------
  // Fine > 200  -> the WHOLE fine is expected on her loan.
  // Fine <= 200 -> the company absorbs it and nothing is expected.
  // The boundary is strict `>`, evidenced twice live (maids 140621 and 63850 both
  // carry a fine of exactly 200 and neither has any OVERSTAY_FINES_FEES loan).
  // Never loan only the excess above 200 — maid 65488's 2,750 fine became a 2,750
  // loan, not 2,550.
  const net = base.fine_net || 0;
  const above = net > THRESHOLD;
  base.expected_aed = above ? r2(net) : 0;

  // ---- Gate 6 — a recovered fine below two hundred is MENTIONED ----------
  if (!above) {
    if (base.loan_sum > 0) {
      base.sub200_recovered_aed = base.loan_sum;
      base.mentions.push('sub-200 recovered anyway: fine ' + net + ', loaned ' + base.loan_sum);
    }
    // Never raise it as a red flag — recovering it is not a failure to recover.
    // Never drop it silently either.
    cases.push(Object.assign(base, {
      gap_aed: 0,
      state: base.needs_verifier ? 'pending' : 'green',
      reason_code: base.loan_sum > 0 ? 'sub200_recovered' : 'sub200_absorbed',
      reason_text: 'Fine of ' + net + ' is at or below the ' + THRESHOLD +
        ' trigger, so the company absorbs it and nothing was expected on her loan.' +
        (base.loan_sum > 0 ? ' It was nonetheless loaned to her (' + base.loan_sum + ') — mentioned, not scored.' : '')
    }));
    continue;
  }

  // ---- Gate 8 — recovery is the SUM of OVERSTAY_FINES_FEES loans ---------
  const gap = r2(base.expected_aed - base.loan_sum);
  base.gap_aed = gap > 0 ? gap : 0;

  // ---- Gate 10 — an unmatched extra loan is MENTIONED, never over-recovery
  // Loans are summed, not paired to transactions.  Never let the surplus offset a
  // shortfall on a different fine — it is recorded, and it never moves gap_aed.
  if (base.loan_sum > base.expected_aed) {
    base.surplus_aed = r2(base.loan_sum - base.expected_aed);
    base.mentions.push('unmatched extra OVERSTAY_FINES_FEES loan(s) totalling ' +
                       base.surplus_aed + ' beyond this fine — mentioned, never an over-recovery finding');
  }

  // ---- Gate 9 — a WAIVED loan is routed to the verifier, never auto-cleared
  // A waived loan and an unrecovered fine are identical on the numbers; only the
  // note separates an authorised decision from money quietly absorbed.
  // waivedAmount 0.0 is the NORMAL value on an unwaived loan — every one of the
  // 27 read live carried 0.0 — so it is never itself read as a waiver.
  if (base.waived_sum > 0) {
    cases.push(Object.assign(base, {
      needs_verifier: true, state: 'pending',
      reason_code: 'loan_waived',
      reason_text: 'An OVERSTAY_FINES_FEES loan of ' + base.loan_sum + ' exists against a fine of ' +
        net + ', but ' + base.waived_sum + ' of it was written off. Routed to the verifier: the amount alone cannot say whether that was authorised.'
    }));
    continue;
  }

  if (base.loan_sum + 0.005 >= base.expected_aed) {
    cases.push(Object.assign(base, {
      state: base.needs_verifier ? 'pending' : 'green',
      reason_code: 'recovered',
      reason_text: 'Fine of ' + net + ' exceeds the ' + THRESHOLD + ' trigger and ' +
        base.loan_sum + ' was put on her loan. Recovered in full.'
    }));
    continue;
  }

  cases.push(Object.assign(base, {
    state: 'red',
    reason_code: base.loan_sum === 0 ? 'never_loaned' : 'short_loan',
    reason_text: base.loan_sum === 0
      ? 'Fine of ' + net + ' exceeds the ' + THRESHOLD +
        ' trigger, so the whole fine was expected on her loan, and no OVERSTAY_FINES_FEES loan exists on her profile. Nothing was recovered.'
      : 'Fine of ' + net + ' exceeds the ' + THRESHOLD + ' trigger but only ' +
        base.loan_sum + ' was put on her loan — short by ' + base.gap_aed + '.'
  }));
}

const count = (s) => cases.filter((x) => x.state === s).length;

return [{
  json: {
    cases,
    excluded_mv,
    intake_stats,
    // Read straight from the node that OWNS it.  Never from whatever survived
    // three transforms — that is how the MV Runs row ended up with `{}`.
    population: $('Verify Cohort Pull').first().json.population,
    provisional_stats: {
      cases_scored: cases.length,
      red: count('red'), green: count('green'),
      pending: count('pending'), review: count('review'),
      excluded_mv: excluded_mv.length,
      needs_verifier: cases.filter((x) => x.needs_verifier).length
    },
    scored_at: new Date().toISOString()
  },
  pairedItem: { item: 0 }
}];

// Select Verifier Cases — runOnceForAllItems.
//
// THIS BAND RUNS BEFORE the case payload, the summary and the table writes.  On
// the MV build the verifier sat in a late band AFTER the results callback and
// after `Write Cases`, so the run summary described itself as "provisional", the
// Cases table permanently held the pre-AI deterministic verdict and nothing ever
// corrected it.  Here the AI verdict is folded in first, and Cases / Runs carry
// FINAL states and correct red/green counts in a single pass.
//
// Only cases the deterministic gates could NOT settle reach the model:
//   * gate 9  — an OVERSTAY_FINES_FEES loan carries a non-zero waivedAmount
//   * rule 2  — the fine carries a reducedAmount whose reason does not settle it
// Everything else is arithmetic and stays arithmetic.  Handing settled cases to a
// model reproduces its false-positive rate for no gain.
//
// PAIRED ITEM: this node reshapes in Run-Once-for-All-Items mode, so it sets
// pairedItem itself.  There is exactly one input item, so { item: 0 } is honest.

const env = $input.first().json;
const cases = env.cases || [];

const picked = cases.filter((c) => c.needs_verifier === true && c.maid_id);

// ZERO verifier cases is the NORMAL outcome — nine months of live data contain no
// waived overstay loan at all.  Emitting nothing here would strand the entire
// delivery band behind an empty branch: no Cases rows, no Runs row, no record
// that the run happened.  The sentinel is routed AROUND the evidence and model
// nodes straight to the sync barrier, so `Merge Agent Verdicts` always executes.
if (picked.length === 0) {
  return [{ json: { no_verifier_cases: true }, pairedItem: { item: 0 } }];
}

// A case that needs judging but has NO maid id cannot have her complaints read.
// It is left where it is (review/pending) rather than pointed at a stranger.
return picked.map((c) => ({
  json: {
    case_key: c.case_key,
    maid_id: c.maid_id,
    maid_name: c.maid_name,
    reason_code: c.reason_code,
    fine_net: c.fine_net,
    expected_aed: c.expected_aed,
    loan_sum: c.loan_sum,
    waived_sum: c.waived_sum,
    waive_notes: c.waive_notes,
    repayment_notes: c.repayment_notes,
    fine_reduced_amount: c.fine_reduced_amount,
    fine_reduction_reason: c.fine_reduction_reason
  },
  pairedItem: { item: 0 }
}));

// Split Relevant Complaints — runOnceForAllItems.
//
// One item in (the maid's complaint list for one case), one item out per
// complaint whose thread must be read.
//
// PAGINATION.  The ERP Variables row warns the list "caps at 40 rows on page 0
// while reporting the true totalElements".  MEASURED 2026-08-12 on twelve maids:
// that cap is the DEFAULT page size, not a server cap — at `size=200` maid 113572
// returned all 74 rows, 105241 all 66, 117027 all 49, every one with
// content.length == totalElements.  So the node in front asks for 200 in a single
// call and this node ASSERTS completeness rather than assuming it.  A truncated
// list is recorded on every case it produced and hard-blocks a "clean (explained)"
// verdict resting on the absence of evidence.
//
// NEVER filter by complaintType.  Not one of the four types on the live sample is
// overstay-related, and on the CC Maids Salary Raise check the relevant To-dos
// appeared under at least seven different type labels.  Filtering finds a
// fraction of them.  The keyword scan below only decides which threads are worth
// a call — it is never itself evidence, and a case with no keyword hit still
// carries every complaint's initialDescription to the model.

const out = [];
const items = $input.all();
const sources = $('Select Verifier Cases').all();

// The index alignment below is only sound because the HTTP node in front returns
// EXACTLY ONE item per input item — which is what `fullResponse: true` guarantees
// and what an un-guarded bare-array response destroys.  Assert it rather than
// trust it: a silent off-by-one here attaches one maid's complaints to another
// maid's case, which is the same class of failure as `.first()` in place of
// `.item`.
if (items.length !== sources.length) {
  throw new Error('Complaint pages (' + items.length + ') != verifier cases (' +
    sources.length + '). The response shape changed; refusing to guess which ' +
    'complaints belong to which maid.');
}

// Guard the response shape before trusting it.  n8n splits a bare top-level array
// into one item per element; this endpoint returns an ENVELOPE, so a missing
// `content` means the shape changed, not that the maid has no complaints.
for (let idx = 0; idx < items.length; idx++) {
  const body = items[idx].json.body !== undefined ? items[idx].json.body : items[idx].json;
  const src = sources[idx];
  if (!src) throw new Error('No verifier case for complaint page ' + idx + ' — item linking is broken.');
  const carry = src.json;

  const content = (body && body.content) || [];
  const total = (body && typeof body.totalElements === 'number') ? body.totalElements : null;
  const complete = Array.isArray(content) && total !== null && content.length === total;

  const rows = (Array.isArray(content) ? content : []).map((x) => ({
    complaint_id: String(x.id),
    // The staff member's opening statement of WHY the ticket was opened — a
    // primary staff-written source, already on the list response at no extra
    // call.  ERP's own `summary` / `recentSummary` are auto-generated, frequently
    // blank, and have already produced a wrong verdict elsewhere in this
    // workspace.  They are not read anywhere in this workflow.
    initial_description: typeof x.initialDescription === 'string' ? x.initialDescription : '',
    manager_notes: typeof x.managerNotes === 'string' ? x.managerNotes : '',
    complaint_type: ((x.complaintType || {}).label) || '',
    status: typeof x.status === 'string' ? x.status : ((x.status || {}).label || ''),
    comment_count: Number(x.commentCount) || 0,
    complaint_date: x.complaintDate || '',
    link: 'https://erp.maids.cc/post-sale-services/open-todo/' + x.id
  }));

  // Only pull the thread where commentCount > 0, and only where the text is worth
  // reading.  The scan decides CALLS, not verdicts.
  const KEY = /(waiv|waive|write[- ]?off|written off|forgiv|cancel|overstay|fine|loan|deduct|absorb|not her fault|approved|approval|refund)/i;
  const worth = rows.filter((r) => r.comment_count > 0 &&
    (KEY.test(r.initial_description) || KEY.test(r.manager_notes) || KEY.test(r.complaint_type)));

  // Every case gets one carrier item even when no thread is worth fetching, so a
  // maid with zero complaints never silently disappears from the verifier band.
  if (worth.length === 0) {
    out.push({
      json: Object.assign({}, carry, {
        complaint_id: '', complaints_all: rows, complaints_total: total,
        complaints_complete: complete, no_thread: true
      }),
      pairedItem: { item: idx }
    });
    continue;
  }
  for (const r of worth) {
    out.push({
      json: Object.assign({}, carry, r, {
        complaints_all: rows, complaints_total: total,
        complaints_complete: complete, no_thread: false
      }),
      pairedItem: { item: idx }
    });
  }
}

return out;

// Attach Threads to Cases — runOnceForAllItems.
//
// Folds every fetched comment thread back onto its case.  A missing thread shows
// as an EMPTY ARRAY, never as "no complaint" — the two are different claims and
// only one of them is evidence.
//
// content[].text is HTML.  It carries <p>, <br>, &nbsp; and whole embedded <div>
// blocks.  It is stripped HERE, before the model ever sees it, and raw markup is
// never quoted into a case.
//
// PAIRED ITEM set explicitly: reshaping node, Run-Once-for-All-Items.

const items = $input.all();
const sources = $('Split Relevant Complaints').all();
if (items.length !== sources.length) {
  throw new Error('Thread responses (' + items.length + ') != complaint rows (' +
    sources.length + '). Refusing to attach a thread to the wrong complaint.');
}

function stripHtml(s) {
  if (typeof s !== 'string') return '';
  return s
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr|h[1-6])>/gi, '\n')
    .replace(/<[^>]*>/g, ' ')
    .replace(/&nbsp;/gi, ' ')
    .replace(/&amp;/gi, '&').replace(/&lt;/gi, '<').replace(/&gt;/gi, '>')
    .replace(/&quot;/gi, '"').replace(/&#39;/gi, "'")
    .replace(/[ \t]+/g, ' ')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const byCase = {};

for (let idx = 0; idx < items.length; idx++) {
  const carry = sources[idx].json;
  const key = carry.case_key;
  if (!byCase[key]) {
    byCase[key] = {
      case_key: key,
      maid_id: carry.maid_id,
      maid_name: carry.maid_name,
      reason_code: carry.reason_code,
      fine_net: carry.fine_net,
      expected_aed: carry.expected_aed,
      loan_sum: carry.loan_sum,
      waived_sum: carry.waived_sum,
      waive_notes: carry.waive_notes,
      repayment_notes: carry.repayment_notes,
      fine_reduced_amount: carry.fine_reduced_amount,
      fine_reduction_reason: carry.fine_reduction_reason,
      complaints_total: carry.complaints_total,
      complaints_complete: carry.complaints_complete,
      complaints_all: carry.complaints_all || [],
      threads: []
    };
  }
  if (carry.no_thread || !carry.complaint_id) continue;

  const body = items[idx].json.body !== undefined ? items[idx].json.body : items[idx].json;
  const content = (body && body.content) || [];
  const comments = (Array.isArray(content) ? content : []).map((x) => ({
    text: stripHtml(x.text),
    creator: x.creator || '',
    team: x.team || '',
    creation_date: x.creationDate || ''
  })).filter((x) => x.text);

  byCase[key].threads.push({
    complaint_id: carry.complaint_id,
    complaint_type: carry.complaint_type,
    initial_description: carry.initial_description,
    link: carry.link,
    comment_count_reported: carry.comment_count,
    comments_read: comments.length,
    comments
  });
}

return Object.keys(byCase).map((k) => ({
  json: byCase[k],
  pairedItem: { item: 0 }
}));

// Build Evidence Bundle — runOnceForAllItems.
//
// Pre-computes the arithmetic so the model cannot invent a different expectation,
// and settles in CODE the shapes that do not need judgement at all.  Whatever the
// model is asked, it is never asked what the numbers are.
//
// PAIRED ITEM set explicitly.

const items = $input.all();
const out = [];

const r2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

for (let i = 0; i < items.length; i++) {
  const c = items[i].json;

  const evidence = [];
  if (c.waive_notes) {
    evidence.push({
      source: 'loan.waiveNotes',
      text: c.waive_notes,
      link: 'https://erp.maids.cc/housemaid/housemaid-profile/details/' + c.maid_id
    });
  }
  if (c.repayment_notes) {
    evidence.push({
      source: 'loan.repaymentNotes',
      text: c.repayment_notes,
      link: 'https://erp.maids.cc/housemaid/housemaid-profile/details/' + c.maid_id
    });
  }
  if (c.fine_reduction_reason) {
    evidence.push({
      source: 'fine.reductionReason',
      text: String(c.fine_reduction_reason),
      link: 'https://erp.maids.cc/housemaid/housemaid-profile/details/' + c.maid_id
    });
  }
  for (const t of (c.threads || [])) {
    if (t.initial_description) {
      evidence.push({
        source: 'complaint ' + t.complaint_id + ' · initialDescription (' + t.complaint_type + ')',
        text: t.initial_description, link: t.link
      });
    }
    for (const m of t.comments) {
      evidence.push({
        source: 'complaint ' + t.complaint_id + ' · comment by ' + (m.creator || 'unknown') +
                ' on ' + (m.creation_date || 'unknown date'),
        text: m.text, link: t.link
      });
    }
  }
  // Complaints that carried no keyword hit still count as read — their
  // initialDescription is listed so "nothing on her record explains it" is a
  // statement about the whole record, not about the four we happened to open.
  const unread = (c.complaints_all || []).filter(
    (x) => !(c.threads || []).some((t) => t.complaint_id === x.complaint_id));
  for (const x of unread) {
    if (x.initial_description) {
      evidence.push({
        source: 'complaint ' + x.complaint_id + ' · initialDescription (' + x.complaint_type +
                ', thread not opened)',
        text: x.initial_description, link: x.link
      });
    }
  }

  const facts = {
    case_key: c.case_key,
    maid_id: c.maid_id,
    fine_net: c.fine_net,
    expected_aed: c.expected_aed,
    loan_principal_total: c.loan_sum,
    waived_amount: c.waived_sum,
    fine_reduced_amount: c.fine_reduced_amount,
    amount_actually_absorbed: r2((c.waived_sum || 0) + (c.fine_reduced_amount || 0)),
    reason_code: c.reason_code,
    complaints_seen: (c.complaints_all || []).length,
    complaints_total_reported: c.complaints_total,
    complaints_complete: c.complaints_complete !== false,
    threads_read: (c.threads || []).length,
    comments_read: (c.threads || []).reduce((a, t) => a + t.comments.length, 0),
    evidence_pieces: evidence.length
  };

  // Settled in code, so the model is never asked a question whose answer is
  // already known.  Both presets refuse to CLEAR — neither invents a clearance.
  let preset_verdict = '';
  if (evidence.length === 0) {
    preset_verdict = 'Written off without justification';
  } else if (facts.complaints_complete === false && !c.waive_notes && !c.fine_reduction_reason) {
    // The only possible justification would have been in complaints we could not
    // read in full.  Never call that unexplained, and never call it clean.
    preset_verdict = 'Awaiting accounting decision';
  }

  const lines = [];
  lines.push('CASE ' + c.case_key + ' — maid ' + c.maid_id + (c.maid_name ? ' (' + c.maid_name + ')' : ''));
  lines.push('Fine net owed by the maid: AED ' + c.fine_net + '. Expected on her loan: AED ' + c.expected_aed + '.');
  lines.push('OVERSTAY_FINES_FEES loan principal on her profile: AED ' + c.loan_sum + '.');
  lines.push('Written off on the loan (waivedAmount): AED ' + c.waived_sum + '.');
  lines.push('Reduced on the fine record (reducedAmount): AED ' + (c.fine_reduced_amount || 0) +
             '; stated reason: ' + (c.fine_reduction_reason ? '"' + c.fine_reduction_reason + '"' : 'BLANK'));
  lines.push('Her complaint record: ' + facts.complaints_seen + ' of ' +
             (c.complaints_total === null || c.complaints_total === undefined ? 'unknown' : c.complaints_total) +
             ' complaints read' + (facts.complaints_complete ? '' : ' — INCOMPLETE, rows are missing') +
             '; ' + facts.threads_read + ' threads opened, ' + facts.comments_read + ' comments read.');
  lines.push('');
  lines.push('EVIDENCE (this is the whole of it — there is no other source):');
  if (evidence.length === 0) lines.push('  (nothing. No waive note, no reduction reason, nothing on her complaints.)');
  for (const e of evidence) lines.push('  [' + e.source + '] ' + e.text);

  out.push({
    json: {
      case_key: c.case_key,
      maid_id: c.maid_id,
      preset_verdict,
      facts,
      evidence,
      prompt: lines.join('\n')
    },
    pairedItem: { item: i }
  });
}

return out;

parameters.inputSchema:
{
  "type": "object",
  "required": ["verdict", "confidence", "reasoning", "quote", "quote_source", "quote_link", "justification_states_why", "route_to"],
  "properties": {
    "verdict": {
      "type": "string",
      "enum": [
        "All is good - waiver justified",
        "Written off without justification",
        "Awaiting accounting decision"
      ],
      "description": "One of the three, exactly as written. Never paraphrased."
    },
    "confidence": {
      "type": "string",
      "enum": ["high", "medium", "low"],
      "description": "A low-confidence clearance is not a clearance - return 'Awaiting accounting decision' instead."
    },
    "reasoning": {
      "type": "string",
      "description": "Two or three sentences. Say which piece of evidence settled it and why the others did not."
    },
    "quote": {
      "type": "string",
      "description": "The VERBATIM sentence the verdict rests on, copied character for character from the evidence. Empty string only when the verdict is not a clearance and no sentence is being relied on."
    },
    "quote_source": {
      "type": "string",
      "description": "Which evidence line the quote came from, e.g. 'loan.waiveNotes' or 'complaint 760247 comment by Sidra Brahim'."
    },
    "quote_link": {
      "type": "string",
      "description": "The link carried on that evidence line, so a human can open it and check."
    },
    "justification_states_why": {
      "type": "boolean",
      "description": "True only if the quoted text states the GROUND on which the write-off was allowed, not merely what was done or by whom."
    },
    "route_to": {
      "type": "string",
      "enum": ["none", "accounting", "payroll", "auditor"],
      "description": "Who has to act next. 'none' when the case is cleared."
    },
    "amount_absorbed_aed": {
      "type": "number",
      "description": "Echo of the amount written off, as given in the facts. Never recomputed."
    }
  }
}

parameters.jsCode:
// Merge Agent Verdicts — runOnceForAllItems.
//
// Folds every verdict back onto its case and produces the FINAL state.  This node
// runs BEFORE the case payload, the run summary and all three table writes, so
// what those write is final, not provisional.
//
// If the verifier band produced nothing — the normal outcome, since nine months of
// live data contain zero waived overstay loans — the deterministic cases pass
// through untouched and the run is still complete.

const env = $('Compute Case States').first().json;
const cases = JSON.parse(JSON.stringify(env.cases || []));

const verdicts = [];
const byKey = {};

for (const it of $input.all()) {
  const j = it.json || {};
  if (j.no_verifier_cases === true) continue;   // the no-cases sentinel
  // The gate's false branch carries the preset straight through; the model branch
  // wraps its answer in `output`.  Both shapes land here via the sync barrier.
  const model = j.output || j.verdict ? (j.output || j) : null;
  const key = j.case_key || (j.facts || {}).case_key;
  if (!key) continue;
  const preset = j.preset_verdict || '';
  const src = (model && model.verdict) ? model : null;

  const v = {
    case_key: key,
    verdict: src ? src.verdict : preset,
    decided_by: src ? 'model' : (preset ? 'preset' : 'none'),
    confidence: src ? (src.confidence || '') : (preset ? 'high' : ''),
    reasoning: src ? (src.reasoning || '') : presetReason(preset, j),
    quote: src ? (src.quote || '') : '',
    quote_source: src ? (src.quote_source || '') : '',
    quote_link: src ? (src.quote_link || '') : '',
    justification_states_why: src ? !!src.justification_states_why : false,
    route_to: src ? (src.route_to || 'auditor') : (preset ? 'accounting' : 'auditor'),
    amount_absorbed_aed: (j.facts || {}).amount_actually_absorbed,
    complaints_read: (j.facts || {}).complaints_seen,
    comments_read: (j.facts || {}).comments_read,
    complaints_complete: (j.facts || {}).complaints_complete,
    evidence_pieces: (j.facts || {}).evidence_pieces,
    // True when the model was needed and did not answer.  A silent model must
    // never look like a clean case.
    verifier_down: !src && !preset,
    reviewed_at: new Date().toISOString()
  };
  verdicts.push(v);
  byKey[key] = v;
}

function presetReason(p, j) {
  if (p === 'Written off without justification') {
    return 'Settled in code: there is no waive note, no reduction reason and nothing on her complaints. There is no text to read, so the model was not asked.';
  }
  if (p === 'Awaiting accounting decision') {
    return 'Settled in code: her complaint list came back incomplete, so a justification may exist in rows that could not be read. Never cleared on absent evidence.';
  }
  return '';
}

// A clearance must carry a quote.  Rule 6 is enforced HERE as well as in the
// prompt, because a prompt is a request and this is a guarantee.
for (const v of verdicts) {
  if (v.verdict === 'All is good - waiver justified' &&
      (!v.quote || !String(v.quote).trim() || !v.justification_states_why)) {
    v.verdict = 'Awaiting accounting decision';
    v.route_to = 'auditor';
    v.downgraded = true;
    v.reasoning = 'Downgraded automatically: a clearance was returned without a ' +
      'quoted sentence that states why the write-off was allowed. ' + (v.reasoning || '');
  }
}

for (const c of cases) {
  const v = byKey[c.case_key];
  if (!v) continue;
  c.verifier_verdict = v.verdict;
  c.verifier_quote = v.quote;
  c.verifier_link = v.quote_link;
  c.decided_by = v.decided_by;
  if (v.verifier_down) {
    c.state = 'review';
    c.reason_code = 'verifier_down';
    c.reason_text = 'This case needed a written justification read and the verifier returned nothing. Never scored either way.';
  } else if (v.verdict === 'All is good - waiver justified') {
    c.state = 'green';
    c.reason_code = 'waiver_justified';
    c.reason_text = 'Write-off justified on the record: "' + v.quote + '" (' + v.quote_source + ').';
  } else if (v.verdict === 'Written off without justification') {
    c.state = 'red';
    c.reason_code = 'written_off_unjustified';
    c.reason_text = 'AED ' + (v.amount_absorbed_aed || c.waived_sum) +
      ' was written off and nothing on the record says why. ' + (v.reasoning || '');
  } else {
    c.state = 'pending';
    c.reason_code = 'awaiting_accounting';
    c.reason_text = v.reasoning || 'Not settled, and not a finding.';
  }
}

const count = (s) => cases.filter((x) => x.state === s).length;

return [{
  json: {
    cases,
    verdicts,
    excluded_mv: env.excluded_mv || [],
    intake_stats: env.intake_stats || {},
    population: env.population || {},
    final_stats: {
      cases_scored: cases.length,
      red: count('red'), green: count('green'),
      pending: count('pending'), review: count('review'),
      verdicts_written: verdicts.length,
      verifier_down: verdicts.filter((v) => v.verifier_down).length
    },
    scored_at: env.scored_at,
    finalised_at: new Date().toISOString()
  },
  pairedItem: { item: 0 }
}];

// Adjudicate Cases — runOnceForAllItems.
//
// Never re-derives an expectation.  It reads what Compute Case States published
// and what Merge Agent Verdicts finalised, and assembles the report lines the
// check page asks for:
//   * red flags, SPLIT BY "never loaned" and "written off without justification"
//     — kept separate so the two are not read as the same failure
//   * sub-200 fines recovered anyway  (mention)
//   * unmatched extra OVERSTAY_FINES_FEES loans  (mention)
//   * review
// Outstanding money counts ONLY billable reds.  A surplus never offsets a gap.

const env = $input.first().json;
const cases = env.cases || [];
const r2 = (n) => Math.round((n + Number.EPSILON) * 100) / 100;

const by = (s) => cases.filter((c) => c.state === s);
const red = by('red');
const green = by('green');
const pending = by('pending');
const review = by('review');

const red_never_loaned = red.filter((c) => c.reason_code === 'never_loaned');
const red_short = red.filter((c) => c.reason_code === 'short_loan');
const red_written_off = red.filter((c) => c.reason_code === 'written_off_unjustified');

const sub200_recovered = cases.filter((c) => (c.sub200_recovered_aed || 0) > 0);
const surplus_cases = cases.filter((c) => (c.surplus_aed || 0) > 0);
const data_quality = cases.filter((c) => c.days_x50_ok === false);
const no_fine_record = review.filter((c) => c.reason_code === 'no_fine_record');

const outstanding_aed = r2(red.reduce((a, c) => a + (c.gap_aed || 0), 0));

const overall = red.length > 0 ? 'findings'
  : (pending.length > 0 || review.length > 0) ? 'attention'
  : 'clean';

const report_lines = {
  red_never_loaned: {
    count: red_never_loaned.length,
    aed: r2(red_never_loaned.reduce((a, c) => a + (c.gap_aed || 0), 0))
  },
  red_short_loan: {
    count: red_short.length,
    aed: r2(red_short.reduce((a, c) => a + (c.gap_aed || 0), 0))
  },
  red_written_off_without_justification: {
    count: red_written_off.length,
    aed: r2(red_written_off.reduce((a, c) => a + (c.waived_sum || 0), 0))
  },
  sub200_recovered_anyway: {
    count: sub200_recovered.length,
    aed: r2(sub200_recovered.reduce((a, c) => a + (c.sub200_recovered_aed || 0), 0))
  },
  unmatched_extra_loans: {
    count: surplus_cases.length,
    aed: r2(surplus_cases.reduce((a, c) => a + (c.surplus_aed || 0), 0))
  },
  data_quality_days_x50: { count: data_quality.length },
  no_fine_record: { count: no_fine_record.length },
  pending: { count: pending.length },
  review: { count: review.length }
};

return [{
  json: Object.assign({}, env, {
    summary: {
      cases_scored: cases.length,
      red: red.length, green: green.length,
      pending: pending.length, review: review.length,
      excluded_mv: (env.excluded_mv || []).length,
      outstanding_aed,
      overall
    },
    report_lines,
    adjudicated_at: new Date().toISOString()
  }),
  pairedItem: { item: 0 }
}];

// Build Case Rows — runOnceForAllItems.  One row per case for the Cases table.
//
// These rows carry FINAL states: this node sits after the verifier, not before
// it, so the table never holds a pre-AI verdict that nothing later corrects.
//
// NULL IS NOT ZERO.  Where there is no authoritative amount the numeric key is
// OMITTED, never written as 0 — a 0 in `fine_net` would read as "we checked and
// she owes nothing", which is a different claim from "we could not read it".
//
// Per-maid amounts live here and in the workbook.  They never reach the chat, the
// run summary or the portal, which carry counts, totals and flags only.  No phone
// number is carried anywhere in this workflow.

const env = $input.first().json;
const run = $('Build Run Context').first().json;
const rows = [];

for (const c of env.cases || []) {
  const r = {
    run_id: run.run_id,
    case_key: String(c.case_key),
    txn_id: String(c.txn_id),
    txn_date: c.txn_date || '',
    maid_id: String(c.maid_id || ''),
    maid_name: c.maid_name || '',
    housemaid_type: c.housemaid_type || '',
    fine_id: c.fine_id || '',
    excess_shape: c.excess_shape || '',
    days_x50_ok: c.days_x50_ok === true,
    os_loan_count: c.os_loan_count || 0,
    state: c.state,
    reason_code: c.reason_code,
    reason_text: c.reason_text,
    verifier_verdict: c.verifier_verdict || '',
    verifier_quote: c.verifier_quote || '',
    decided_by: c.decided_by || 'deterministic',
    mentions: (c.mentions || []).join(' | '),
    maid_link: c.maid_id ? 'https://erp.maids.cc/housemaid/housemaid-profile/details/' + c.maid_id : '',
    scored_at: env.scored_at || ''
  };
  const numeric = {
    txn_amount: c.txn_amount, excess: c.excess,
    fine_gross: c.fine_gross, fine_net: c.fine_net, fine_days: c.fine_days,
    reduced_amount: c.fine_reduced_amount,
    expected_aed: c.expected_aed, recovered_aed: c.loan_sum,
    gap_aed: c.gap_aed, surplus_aed: c.surplus_aed,
    waived_aed: c.waived_sum, sub200_recovered_aed: c.sub200_recovered_aed
  };
  for (const k of Object.keys(numeric)) {
    const v = numeric[k];
    if (typeof v === 'number' && isFinite(v)) r[k] = v;   // omitted otherwise
  }
  r.reduction_reason = c.fine_reduction_reason || '';
  rows.push({ json: r, pairedItem: { item: 0 } });
}

// Never emit zero items: the table write would be skipped and a genuinely empty
// month would leave no trace at all.  One marker row says the run looked.
if (rows.length === 0) {
  rows.push({
    json: {
      run_id: run.run_id, case_key: run.run_id + '-no-cases', txn_id: '',
      state: 'none', reason_code: 'no_cases',
      reason_text: 'The window contained CC change-of-status transactions but none carried an amount above the base, so there was nothing to score.',
      scored_at: env.scored_at || ''
    },
    pairedItem: { item: 0 }
  });
}

return rows;

// Build Verdict Rows — runOnceForAllItems.  One row per AI verdict.
//
// The MV build CREATED a Verdicts table and then referenced it from no node at
// all, and shipped a `recovery_followup` column nothing anywhere writes.  EVERY
// column below has a producer in this file — if a column is here, something fills
// it, and if nothing fills it, it is not here.
//
// Joined to Cases on `case_key`.
//
// Only the verdict and the quoted justification leave the check.  Nothing in this
// row carries a personal detail: the quote is the model's, bound by hard stop 10
// of the system message, and the amounts are the ones already in the Cases table.

const env = $input.first().json;
const run = $('Build Run Context').first().json;
const verdicts = env.verdicts || [];

if (verdicts.length === 0) {
  // Nothing ran the model. That is the normal state for this check, and it is
  // recorded as such rather than as an empty table nobody can interpret.
  return [{
    json: {
      run_id: run.run_id,
      case_key: run.run_id + '-no-verdicts',
      verdict: 'n/a - no case required judgement',
      decided_by: 'none',
      confidence: '',
      reasoning: 'No case in this window carried a waived loan or an unsettled fine reduction, so the verifier had nothing to judge.',
      quote: '', quote_source: '', quote_link: '',
      justification_states_why: false,
      route_to: 'none',
      complaints_read: 0, comments_read: 0,
      complaints_complete: true,
      evidence_pieces: 0,
      verifier_down: false,
      downgraded: false,
      reviewed_at: new Date().toISOString()
    },
    pairedItem: { item: 0 }
  }];
}

return verdicts.map((v) => {
  const row = {
    run_id: run.run_id,
    case_key: String(v.case_key),
    verdict: v.verdict || '',
    decided_by: v.decided_by || '',
    confidence: v.confidence || '',
    reasoning: v.reasoning || '',
    quote: v.quote || '',
    quote_source: v.quote_source || '',
    quote_link: v.quote_link || '',
    justification_states_why: v.justification_states_why === true,
    route_to: v.route_to || '',
    complaints_read: Number(v.complaints_read) || 0,
    comments_read: Number(v.comments_read) || 0,
    complaints_complete: v.complaints_complete !== false,
    evidence_pieces: Number(v.evidence_pieces) || 0,
    verifier_down: v.verifier_down === true,
    downgraded: v.downgraded === true,
    reviewed_at: v.reviewed_at || new Date().toISOString()
  };
  if (typeof v.amount_absorbed_aed === 'number' && isFinite(v.amount_absorbed_aed)) {
    row.amount_absorbed_aed = v.amount_absorbed_aed;   // null is not zero
  }
  return { json: row, pairedItem: { item: 0 } };
});

// Build Run Row — runOnceForAllItems.  One row per run, always.
//
// THE POPULATION PROOF IS READ FROM THE NODE THAT OWNS IT.  `Verify Cohort Pull`
// computed it and this node asks that node for it by name — not whatever survived
// three transforms.  On the MV build the proof arrived as `{}` because an
// intermediate node dropped it, so every run wrote `population_complete: false`
// and stamped itself untrustworthy.
//
// Counts, totals and flags ONLY.  No per-maid amount reaches this row.

const env = $input.first().json;
const run = $('Build Run Context').first().json;
const pop = $('Verify Cohort Pull').first().json.population || {};
const intake = env.intake_stats || {};
const s = env.summary || {};
const rl = env.report_lines || {};

return [{
  json: {
    run_id: run.run_id,
    check_id: run.check_id,
    check_name: run.check_name,
    window_from: run.window_from,
    window_to: run.window_to,
    trigger: run.trigger,
    started_at: run.started_at,

    txns_seen: Number(pop.cohort_count) || 0,
    txns_pages: Number(pop.pages_fetched) || 0,
    population_complete: pop.population_complete === true,
    txns_with_overstay: Number(intake.txns_with_overstay) || 0,
    excluded_at_or_below_base: Number(intake.excluded_at_or_below_base) || 0,
    excluded_mv_maids: Number(s.excluded_mv) || 0,

    cases_scored: Number(s.cases_scored) || 0,
    red: Number(s.red) || 0,
    green: Number(s.green) || 0,
    pending: Number(s.pending) || 0,
    review: Number(s.review) || 0,

    red_never_loaned: Number((rl.red_never_loaned || {}).count) || 0,
    red_short_loan: Number((rl.red_short_loan || {}).count) || 0,
    red_written_off: Number((rl.red_written_off_without_justification || {}).count) || 0,
    sub200_recovered_count: Number((rl.sub200_recovered_anyway || {}).count) || 0,
    sub200_recovered_aed: Number((rl.sub200_recovered_anyway || {}).aed) || 0,
    unmatched_extra_loans_count: Number((rl.unmatched_extra_loans || {}).count) || 0,
    unmatched_extra_loans_aed: Number((rl.unmatched_extra_loans || {}).aed) || 0,
    no_fine_record_count: Number((rl.no_fine_record || {}).count) || 0,
    data_quality_count: Number((rl.data_quality_days_x50 || {}).count) || 0,

    verdicts_written: Number((env.final_stats || {}).verdicts_written) || 0,
    verifier_down: Number((env.final_stats || {}).verifier_down) || 0,

    outstanding_aed: Number(s.outstanding_aed) || 0,
    overall: s.overall || 'unknown',
    notes: 'Threshold ' + run.constants.threshold + ' strict >, base ' + run.constants.base +
      ', expense ' + run.constants.expense_id + '. Verdicts are FINAL: the verifier ran before this row was built.',
    completed_at: new Date().toISOString()
  },
  pairedItem: { item: 0 }
}];

// Build Case Payload — runOnceForAllItems.  The portal envelope.
//
// COUNTS, TOTALS AND FLAGS ONLY.  The per-maid amounts stay in the Cases table and
// the workbook; the portal, the chat and the run summary never carry them. The
// verifier's verdict and its quoted justification are the only free text allowed
// out of this check.
//
// This is ONE OF FIVE independent branches off Adjudicate Cases, not a link in a
// chain.  The three table writes are wired ahead of it so a failing portal
// callback cannot cost the durable record.

const env = $input.first().json;
const run = $('Build Run Context').first().json;
const s = env.summary || {};
const rl = env.report_lines || {};
const pop = $('Verify Cohort Pull').first().json.population || {};

const esc = (t) => String(t === null || t === undefined ? '' : t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const line = (label, o, unit) =>
  '<tr><td>' + esc(label) + '</td><td style="text-align:right">' + (o.count || 0) +
  '</td><td style="text-align:right">' + (o.aed === undefined ? '—' : 'AED ' + o.aed) + '</td></tr>';

const report_html =
  '<h2>' + esc(run.check_name) + ' — ' + esc(run.window_from) + ' to ' + esc(run.window_to) + '</h2>' +
  '<p>' + pop.cohort_count + ' CC change-of-status transactions walked over ' + pop.pages_fetched +
  ' page(s); population complete: <b>' + (pop.population_complete ? 'yes' : 'NO') + '</b>. ' +
  (env.intake_stats || {}).txns_with_overstay + ' carried an amount above the base.</p>' +
  '<p><b>' + s.red + ' finding(s)</b>, ' + s.green + ' clean, ' + s.pending + ' pending, ' +
  s.review + ' for review. Outstanding: <b>AED ' + s.outstanding_aed + '</b>.</p>' +
  '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Line</th><th>Cases</th><th>Amount</th></tr>' +
  line('Not added to her loan', rl.red_never_loaned || {}) +
  line('Loaned short of the fine', rl.red_short_loan || {}) +
  line('Written off without justification', rl.red_written_off_without_justification || {}) +
  line('Sub-200 fines recovered anyway (mention)', rl.sub200_recovered_anyway || {}) +
  line('Unmatched extra overstay loans (mention)', rl.unmatched_extra_loans || {}) +
  line('No fine record against the excess (review)', rl.no_fine_record || {}) +
  line('Fine did not reconcile to days x 50 (data quality)', rl.data_quality_days_x50 || {}) +
  line('Awaiting accounting decision', rl.pending || {}) +
  '</table>' +
  '<p style="color:#666;font-size:12px">Verdict wording on this check is PROPOSED, not confirmed by the team. ' +
  'Threshold AED ' + run.constants.threshold + ', strict &gt;, a trigger not a deductible — the whole fine goes on the maid\'s loan. ' +
  'Expense ' + run.constants.expense_id + '. Do not read MV Overstay Fines constants into this check.</p>';

return [{
  json: {
    check_id: run.check_id,
    run_id: run.run_id,
    callback_url: run.callback_url,
    delivery: run.delivery,
    result: s.overall,
    summary: {
      cases_scored: s.cases_scored, red: s.red, green: s.green,
      pending: s.pending, review: s.review,
      outstanding_aed: s.outstanding_aed,
      population_complete: pop.population_complete === true,
      cohort_count: pop.cohort_count,
      verdicts_written: (env.final_stats || {}).verdicts_written || 0
    },
    report_lines: rl,
    report_html,
    run_note: run.check_name + ': ' + s.red + ' finding(s) across ' + s.cases_scored +
      ' case(s) from ' + pop.cohort_count + ' transactions. Verdicts are final — the verifier ran before delivery.',
    // Case-level detail for the portal carries states and reasons, never amounts.
    cases: (env.cases || []).map((c) => ({
      case_key: c.case_key, state: c.state, reason_code: c.reason_code,
      verifier_verdict: c.verifier_verdict || '', verifier_quote: c.verifier_quote || '',
      link: c.maid_id ? 'https://erp.maids.cc/housemaid/housemaid-profile/details/' + c.maid_id : ''
    }))
  },
  pairedItem: { item: 0 }
}];

// Format Review Email — runOnceForAllItems.
//
// Its OWN branch off Adjudicate Cases, not chained behind the portal callback. On
// the MV build this email sat downstream of a callback that was itself gated on
// `delivery.portal === true` while the runner declared portal:false, so it never
// fired once. A declared target is never reachable only through another target.
//
// The check page answers Email = no, so the Gmail node it feeds is a DRAFT and is
// DISABLED and carries no credential. This node still runs, so the moment the
// answer changes the content is already correct and tested.
//
// Counts, totals and flags only — plus the verifier's verdict and its quote,
// which are the only free text allowed out of this check.

const env = $input.first().json;
const run = $('Build Run Context').first().json;
const s = env.summary || {};
const rl = env.report_lines || {};

const esc = (t) => String(t === null || t === undefined ? '' : t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const needAttention = (env.cases || []).filter(
  (c) => c.state === 'red' || c.state === 'pending' || c.state === 'review');

const rows = needAttention.map((c) =>
  '<tr><td>' + esc(c.case_key) + '</td><td>' + esc(c.state) + '</td><td>' + esc(c.reason_code) +
  '</td><td>' + esc(c.verifier_verdict || '—') + '</td><td>' +
  (c.verifier_quote ? '"' + esc(c.verifier_quote) + '"' : '—') + '</td>' +
  '<td>' + (c.maid_id ? '<a href="https://erp.maids.cc/housemaid/housemaid-profile/details/' +
    esc(c.maid_id) + '">open</a>' : '—') + '</td></tr>').join('');

return [{
  json: {
    subject: '[' + esc(run.check_name) + '] ' + s.red + ' finding(s), ' + s.pending +
             ' pending, ' + s.review + ' review — ' + esc(run.window_from) + ' to ' + esc(run.window_to),
    html:
      '<h2>' + esc(run.check_name) + '</h2>' +
      '<p>' + s.cases_scored + ' case(s) scored. <b>' + s.red + ' finding(s)</b>, ' + s.green +
      ' clean, ' + s.pending + ' pending, ' + s.review + ' for review. Outstanding AED ' +
      s.outstanding_aed + '.</p>' +
      '<p>Report lines — not added to her loan: ' + ((rl.red_never_loaned || {}).count || 0) +
      ' · loaned short: ' + ((rl.red_short_loan || {}).count || 0) +
      ' · written off without justification: ' + ((rl.red_written_off_without_justification || {}).count || 0) +
      ' · sub-200 recovered anyway (mention): ' + ((rl.sub200_recovered_anyway || {}).count || 0) +
      ' · unmatched extra loans (mention): ' + ((rl.unmatched_extra_loans || {}).count || 0) + '.</p>' +
      (rows
        ? '<table border="1" cellpadding="4" cellspacing="0"><tr><th>Case</th><th>State</th>' +
          '<th>Reason</th><th>Verifier</th><th>Quoted justification</th><th>Maid</th></tr>' + rows + '</table>'
        : '<p>Nothing needs a human this run.</p>') +
      '<p style="color:#666;font-size:12px">Verdict wording is PROPOSED and not yet confirmed by the team. ' +
      'Per-maid amounts are deliberately absent — they live in the Cases data table and the workbook.</p>'
  },
  pairedItem: { item: 0 }
}];

// Build Error Run Row — runOnceForAllItems.
//
// A failed run gets a Runs row too. Zeroed counts, `overall: 'error'`, the error
// code, and whatever the population proof had reached before it broke. Without
// this the runs log silently omits exactly the runs a reader most needs to see.
//
// Wired FIRST in the error rail's connection order, ahead of the callback, the
// draft email and the deliberate failure — a durable write must never be the
// thing that a later failing step costs you.

const e = $input.first().json;
const pop = e.population || {};

return [{
  json: {
    run_id: e.run_id,
    check_id: e.check_id,
    check_name: e.check_name,
    window_from: e.window_from || '',
    window_to: e.window_to || '',
    trigger: e.trigger || 'manual',
    started_at: '',

    txns_seen: Number(pop.cohort_count) || 0,
    txns_pages: Number(pop.pages_fetched) || 0,
    population_complete: pop.population_complete === true,
    txns_with_overstay: 0,
    excluded_at_or_below_base: 0,
    excluded_mv_maids: 0,

    cases_scored: 0, red: 0, green: 0, pending: 0, review: 0,
    red_never_loaned: 0, red_short_loan: 0, red_written_off: 0,
    sub200_recovered_count: 0, sub200_recovered_aed: 0,
    unmatched_extra_loans_count: 0, unmatched_extra_loans_aed: 0,
    no_fine_record_count: 0, data_quality_count: 0,
    verdicts_written: 0, verifier_down: 0,
    outstanding_aed: 0,

    overall: 'error',
    notes: 'RUN FAILED (' + (e.error || {}).code + ') at node "' + (e.error || {}).node +
           '": ' + (e.error || {}).message +
           ' — nothing was audited. This row exists so the runs log records the attempt.',
    completed_at: e.failed_at || new Date().toISOString()
  },
  pairedItem: { item: 0 }
}];

// Format Failure Email — runOnceForAllItems.
// Renders a DRAFT only. The check page answers Email = no; escalation stays manual.

const e = $input.first().json;
const esc = (t) => String(t === null || t === undefined ? '' : t)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const err = e.error || {};

const rows = (e.errors || []).map((x) =>
  '<tr><td>' + esc(x.code) + '</td><td>' + esc(x.node) + '</td><td>' + esc(x.status || '—') +
  '</td><td>' + esc(x.message) + '</td><td style="text-align:right">' + (x.occurrences || 1) + '</td></tr>'
).join('');

return [{
  json: {
    subject: '[' + esc(e.check_name) + '] run FAILED — ' + esc(err.code) + ' — ' + esc(e.run_id),
    html:
      '<h2>' + esc(e.check_name) + ' — run failed</h2>' +
      '<p>Run <code>' + esc(e.run_id) + '</code>, window ' + esc(e.window_from) + ' to ' + esc(e.window_to) +
      '. <b>Nothing was audited.</b> A Runs row was written with <code>overall: error</code> so the log records the attempt, ' +
      'and the execution has been failed deliberately — a run that audited nothing must never report success.</p>' +
      '<table border="1" cellpadding="4" cellspacing="0">' +
      '<tr><th>Code</th><th>Node</th><th>HTTP</th><th>Message</th><th>#</th></tr>' + rows + '</table>' +
      '<p style="color:#666;font-size:12px">If the code is <code>erp_auth</code> the ERP credential ' +
      '"ERP Token 11th Aug 2026" has expired and needs replacing by hand — token and cookie together, ' +
      'or the pair mismatches and 500s in a way that looks like a dead token.</p>'
  },
  pairedItem: { item: 0 }
}];

// Fail Loudly (CC Overstay Fines) — the end of the error rail. Replaces `Fail The Run`.
//
// WHY THE RAIL EXISTS. This flow acquires the ERP lease before `Get CC Change of Status
// Transactions` and releases it after `Write Run`. Until this audit there was no lease at all;
// now that there is one, every way this flow can die between those two points — a breaker trip,
// a budget refusal, a dead token, an ERP 500, a paired-item throw — would otherwise leave the
// lease held by a run that no longer exists, and the staleness backstop only clears it after
// three hours. That is a three-hour hole in the queue after every failure.
//
// THE ORDER ON THE RAIL IS DELIBERATE: capture, record, release, THEN fail.
//   Build Error Callback   reads the real error item and names the node that produced it
//   Build Error Run Row    writes the Runs row, so a failed run still has a record it ran
//   Release Lease (error)  hands the lease back
//   Fail Loudly            re-throws
// The release sits after the record rather than before it because nothing between them touches
// ERP, and putting the capture first is the only way `Build Error Callback` sees the failure
// instead of the lease sub-workflow's return value.
//
// WHY IT IS AN ERROR OUTPUT AND NOT THE ERROR TRIGGER. `On Workflow Crash` fires in a SEPARATE
// execution, where `$('Build Run Context')` does not resolve — so it cannot name the run that
// holds the lease, and a release that guesses is the silent-steal path the lease exists to
// prevent. An error OUTPUT stays inside the same execution, so the release names the real
// holder. There is a second reason here specifically: this flow is MANUAL-ONLY, and n8n does not
// fire error workflows for manual executions at all. On the only way this check is ever run, the
// Error Trigger is not a rail — it is decoration.
//
// WHY IT RE-THROWS. n8n marks an execution SUCCESS when it runs off the end of an error output.
// A rail that released and stopped would turn a failed audit into one the run log reports as
// fine — strictly worse than the stranded lease it was added to fix, because a stranded lease is
// loud within three hours and a silently-successful audit is never looked at again.
const item = $input.first().json || {};

// This node sits downstream of `Release Lease (error)`, so the item it receives is the LEASE's
// return value, not the original error. The error was already read, classified and recorded by
// `Build Error Callback`; that node is asked for it by name rather than re-derived here, so
// there is exactly one classification of any given failure in this flow.
let failedNode = 'unknown node';
let message = 'unknown error';
let errorCode = '';
try {
  const e = ($('Build Error Callback').first().json || {}).error || {};
  failedNode = String(e.node || failedNode);
  message = String(e.message || message);
  errorCode = String(e.code || '');
} catch (err) { /* the rail fired before Build Error Callback could run */ }

let runId = 'unknown';
let auditWindow = '';
try {
  const c = $('Build Run Context').first().json;
  runId = String(c.run_id);
  auditWindow = String(c.window_from || '') + ' to ' + String(c.window_to || '');
} catch (err) { /* crashed before intake, or running inside the Error Trigger's execution */ }

// The lease call's own answer, so "was the lease actually handed back?" is a fact in the log
// rather than an assumption. A release from a non-holder is a no-op by construction — which is
// the correct outcome when the rail fired at `Acquire ERP Lease` itself and this run never held
// anything.
const leaseAction = String(item.action || '');
const leaseState = String(item.state || '');

console.log(JSON.stringify({ stage: 'cc_overstay_fines_failed', run_id: runId,
  audit_window: auditWindow, failed_node: failedNode, error_code: errorCode, error: message,
  lease_action: leaseAction || null, lease_state: leaseState || null,
  note: 'ERP lease RELEASED on the error rail. Without it this run would have held the lease ' +
        'until the 3-hour staleness backstop, because Release ERP Lease sits after Write Run ' +
        'and never runs when the flow dies.' }));

throw new Error('CC OVERSTAY FINES FAILED at "' + failedNode + '"' +
  (errorCode ? ' [' + errorCode + ']' : '') + ': ' + message +
  ' | The ERP lease was released (' + (leaseAction || 'no lease action reported') +
  '), so the next audit is not blocked. | Window ' + auditWindow + ', run ' + runId +
  '. | The Cases and Verdicts tables were NOT written for this run, so there is no partial ' +
  'result to mistake for a complete one; the Runs row written by this rail records the failure. ' +
  'Re-run the same window once the cause is fixed.');

// ERP PRE-FLIGHT BUDGET GATE — ERP-LOAD-POLICY.md §3. Canonical: tools/erp_preflight_gate.js.
//
// Sits on the TRUE branch of `Has Cases?`, between it and `Attach Identity`. That is still the
// last point before the first PER-ENTITY ERP call — identity itself no longer costs one (see
// below), so the first such call is now `Get Overstay Fines`: everything upstream is the
// paginated cohort walk, whose cost is a handful of pages whatever the window; everything
// downstream multiplies by the number of over-base transactions.
//
// WHY VOLUME NEEDS ITS OWN CONTROL. Pacing bounds requests per second. It does not bound how
// many there are. This flow paced perfectly at 4 req/s still makes 2N calls for its
// deterministic band alone, and up to 77N once the verifier band fans out - and that is the
// shape of the failure that took ERP down three times: a check tested on one month behaves
// identically on a year, and nothing in between makes the cost visible before the calls go out.
//
// IT HARD-FAILS. It does not trim the cohort to fit. Auto-capping produces a run that completes
// with incomplete coverage, and a partial audit that looks complete is the single failure this
// whole check family exists to avoid. The throw names both numbers so the operator's next move
// is obvious: narrow the window deliberately, or raise the budget deliberately.

// --- per-flow constants: what this run actually costs, stated honestly -----------------------
// The deterministic band, one call each per over-base transaction:
//   1. Get Overstay Fines      - one per transaction with a resolved maid. Still budgeted at one
//                                per transaction rather than per unique maid: a maid can hold
//                                more than one over-base transaction in a window, and budgeting
//                                the deduplicated count would under-project the run it is meant
//                                to bound. A budget that assumes the happy case is not a budget.
//   2. Get Housemaid Loans     - one per case that got past the fines read, worst case one per
//                                transaction.
//
// 2026-08-30: WAS 3. `Get Transaction Detail` - one call per transaction, purely to learn which
// maid a transaction belonged to - is gone. The cohort route moved to the legacy
// /accounting/transactions/page/advancesearch, which projects the `housemaids` link with the
// population, so identity now costs ZERO per-entity calls. This is a real reduction in the
// deterministic band, not a re-estimate: one third of it no longer happens.
const ERP_CALLS_PER_TRANSACTION = 2;

// The verifier band. It is CONDITIONAL - only a case with a waived OVERSTAY_FINES_FEES loan or
// an unsettled fine reduction reaches it - and in nine months of live data measured 2026-08-12
// exactly ZERO cases did. But "usually zero" is not a bound, and this is the band that fans out:
//   3. Get Maid Complaints  - one call per verifier case.
//   4. Get Complaint Thread - one call per complaint the keyword scan selects, PLUS one wasted
//                             call per case with no thread worth reading (that carrier item
//                             still reaches the HTTP node with an empty complaint_id). The
//                             largest complaint list measured live on this endpoint was 74 rows
//                             (maid 113572, 2026-08-12; 66 and 49 on two others), so 74 is the
//                             measured worst case for one maid, not a guess.
const MAX_THREADS_PER_CASE = 74;
const VERIFIER_CALLS_PER_CASE = 1 + MAX_THREADS_PER_CASE;

// Worst case every transaction needs the verifier. That is what makes this projection an upper
// bound rather than a forecast, and the log below prints the realistic floor next to it so the
// operator is deciding between two real numbers instead of one scary one.
const SWEEP_CALLS_FALLBACK = 5;      // cohort pages, when the run cannot report what it walked

const DEFAULT_BUDGET = 2000;         // ERP-LOAD-POLICY.md §1 — a run that names no budget
const SIGNOFF_THRESHOLD = 15000;     // above this a human decision must be recorded first

const _ctx = $('Build Run Context').first().json || {};
const params = _ctx.params || {};

const askedBudget = Number(params.erp_call_budget);
const budget = Number.isFinite(askedBudget) && askedBudget > 0 ? askedBudget : DEFAULT_BUDGET;

// Prefer what the run MEASURED over the constant: `Verify Cohort Pull` already counted the pages
